// Genuary #8: Draw one million of something 

#define PI acos(-1.)

#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a)) 
#define AAstep(thre, val) smoothstep(-.7,.7,(val-thre)/min(.05,fwidth(val-thre)))

vec3 circle (vec2 uv, vec2 offset, float r, vec3 col)
{ return clamp((1.-AAstep(length(uv-offset), r))+col,0.,1.);}

// very naive implementation of ben day dots
vec3 c_grid (vec2 uv, float size)
{
    uv *= rot(PI/12.);
    uv = fract(uv)-0.5;
    return circle(uv,vec2(0.), size, vec3(0., 1.,1.));
}

vec3 m_grid (vec2 uv, float size)
{
    uv *= rot(-PI/4.);
    uv = fract(uv)-0.5;
    return circle(uv,vec2(0.), size, vec3(1., 0.,1.));
}

vec3 y_grid (vec2 uv, float size)
{
    uv = fract(uv)-0.5;
    return circle(uv,vec2(0.), size, vec3(1., 1.,0.));
}

vec3 blue_halftone(vec2 uv)
{
    vec3 c = c_grid(uv, 0.4);
    c *= m_grid(uv, 0.3);
    c *= y_grid(uv, 0.25);
    return c;
}

vec3 green_halftone(vec2 uv)
{
    vec3 c = c_grid(uv, 0.4);
    c *= m_grid(uv, 0.1);
    c *= y_grid(uv, 0.4);
    return c;
}

vec3 red_halftone(vec2 uv)
{
    vec3 c = c_grid(uv, 0.3);
    c *= m_grid(uv, 0.4);
    c *= y_grid(uv, 0.4);
    return c;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec2 uu = (2.*fragCoord.xy - iResolution.xy)/iResolution.y;
    vec4 jcvd = texture(iChannel0, uv);

    float luma = (0.299*jcvd.r + 0.587*jcvd.g + 0.114*jcvd.b);
    luma = floor(luma*2.)/2.;
    vec3 col = (luma < 0.5) ? blue_halftone(uu*100.) : red_halftone(uu*100.);

    // ultra lazy chroma key lul
    float background = (jcvd.g >.6 && jcvd.r < 0.25 && jcvd.b < 0.25) ? 1. : 0.;  
    col = mix(col, green_halftone(uu * 30.), background);

    fragColor = vec4(sqrt(col),1.0);
}
